import subprocess
import time
import threading
def task_func(file_list):
    exit_codes = [None] * len(file_list)
    threads = []

    def run_file(file, index):
        try:
            process = subprocess.Popen(file, shell=True)
            exit_codes[index] = process.wait()
        except Exception:
            exit_codes[index] = -1

    for i, f in enumerate(file_list):
        thread = threading.Thread(target=run_file, args=(f, i))
        thread.start()
        threads.append(thread)

    for thread in threads:
        thread.join()

